      ('tu-van-chon-thiet-bi', 'Tư vấn chọn thiết bị', 'Kiểm tra thông số, đề xuất mã thiết bị phù hợp với ứng dụng và ngân sách.', 'Gửi cho chúng tôi thông số kỹ thuật, bản vẽ hoặc ảnh tem nhãn thiết bị đang dùng. Đội ngũ kỹ thuật sẽ kiểm tra và đề xuất mã phù hợp, kèm các phương án về giá và thời gian giao hàng.', 'chat', 1),
      ('tim-ma-thay-the-tuong-duong', 'Tìm mã thay thế tương đương', 'Hỗ trợ tìm thiết bị thay thế khi mã cũ ngừng sản xuất hoặc khan hàng.', 'Khi thiết bị đang dùng đã ngừng sản xuất hoặc khó tìm, chúng tôi tra cứu và đề xuất mã tương đương từ cùng hãng hoặc hãng khác, đảm bảo tương thích về thông số và kích thước lắp đặt.', 'search', 2),
      ('cung-cap-vat-tu-theo-du-an', 'Cung cấp vật tư theo dự án', 'Báo giá trọn gói theo danh sách vật tư cho dự án, công trình, bảo trì định kỳ.', 'Nhận danh sách vật tư (BOM) theo file Excel, báo giá trọn gói và giao hàng theo tiến độ dự án hoặc kế hoạch bảo trì của nhà máy.', 'box', 3),
      ('giao-hang-tan-noi', 'Giao hàng tận nơi', 'Đóng gói cẩn thận, giao hàng đến tận nhà máy, kho bãi của khách hàng.', 'Hàng được kiểm tra, đóng gói cẩn thận trước khi giao. Chúng tôi giao hàng đến tận nhà máy, kho bãi theo thời gian đã thống nhất với khách hàng.', 'truck', 4),
      ('ho-tro-ky-thuat', 'Hỗ trợ kỹ thuật', 'Hướng dẫn đấu nối, cài đặt cơ bản và hỗ trợ xử lý sự cố sau bán hàng.', 'Hỗ trợ khách hàng về tài liệu kỹ thuật, sơ đồ đấu nối và cài đặt thông số cơ bản cho thiết bị đã mua; tiếp nhận và xử lý yêu cầu bảo hành.', 'cog', 5)
